import json
from pathlib import Path

from strategy import decide


def main():
    bars = []
    for index in range(170):
        close = 100 + index * 0.05
        bars.append({
            "date": f"2024-01-{index + 1:02d}", "open": close,
            "high": close + 0.2, "low": close - 0.2,
            "close": close, "volume": 1000,
        })
    bars[120].update({"high": 100, "low": 99})
    bars[132].update({"close": 75, "high": 76, "low": 70})
    bars[145].update({"close": 98, "high": 98, "low": 97})
    bars[110].update({"close": 80, "high": 80.1, "low": 79.9})
    for index in range(146, 151):
        bars[index].update({"close": 96, "high": 98, "low": 90})
    for index in range(151, 165):
        bars[index].update({"open": 100, "close": 100, "high": 100.2, "low": 99.8})
    for index in range(165, 169):
        bars[index].update({"open": 109.8, "close": 109.8, "high": 109.9, "low": 109.6})
    bars[-1].update({"open": 109, "high": 110, "low": 109, "close": 110, "volume": 1500})
    context = {
        "schema": "strategy-v1", "cutoff": bars[-1]["date"],
        "bars": {"SYNTH": bars},
        "account": {"cash": 10000, "equity": 10000, "positions": {}},
        "state": {}, "previous_orders": [],
    }
    decisions = decide(context)
    transactions = []
    for proposal in decisions["proposals"]:
        if proposal["action"] == "buy":
            transactions.append({
                "symbol": proposal["symbol"], "action": "buy",
                "shares": proposal["sizing"]["shares"], "fill": "not simulated: no next session",
            })
    output = {
        "label": "SYNTHETIC EXAMPLE — not real market data or investment performance evidence",
        "inputs": {"symbol": "SYNTH", "sessions": len(bars), "cutoff": context["cutoff"]},
        "decisions": decisions,
        "simulated_transactions": transactions,
    }
    text = json.dumps(output, indent=2, sort_keys=True)
    print(text)
    Path("result.json").write_text(text + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

