"""Approved numeric cup-with-handle strategy; see README for provenance."""

from decimal import Decimal, ROUND_HALF_UP

SHARES = 100
FEE_RATE = Decimal("0.0005")


def _candidate(bars, index, left, right):
    cup_size = right - left + 1
    handle_size = index - right - 1
    if not (left < right < index and 25 <= cup_size <= 120 and 5 <= handle_size <= 30):
        return None
    bottom = min(range(left, right + 1), key=lambda item: bars[item]["low"])
    if not left < bottom < right:
        return None
    left_high, right_high, bottom_low = (
        bars[left]["high"], bars[right]["high"], bars[bottom]["low"]
    )
    stop = min(item["low"] for item in bars[right + 1:index])
    pivot = max(item["high"] for item in bars[right:index])
    if left_high <= 0 or right_high <= 0 or left < 10:
        return None
    rim_difference = abs(right_high - left_high) / left_high
    depth = (left_high - bottom_low) / left_high
    if not (
        rim_difference <= 0.08 and 0.06 <= depth <= 0.50
        and left_high / bars[left - 10]["close"] - 1 >= 0.15
        and stop >= bottom_low + 0.5 * (left_high - bottom_low)
        and 0 <= (right_high - stop) / right_high <= 0.35
    ):
        return None
    target = pivot + 5 * (right_high - bottom_low)
    close = bars[index]["close"]
    if not (pivot < close <= 1.10 * pivot and close < target and close > stop):
        return None
    return {
        "left": left, "right": right, "bottom": bottom, "stop": stop,
        "pivot": pivot, "target": target, "rim_difference": rim_difference,
        "cup_sessions": cup_size,
    }


def _candidates(bars, index):
    found = []
    first_left = max(10, index - 159)
    for right in range(max(first_left + 24, index - 31), index - 5):
        for left in range(max(first_left, right - 119), right - 24 + 1):
            item = _candidate(bars, index, left, right)
            if item:
                found.append(item)
    found.sort(key=lambda item: (
        item["rim_difference"], -item["cup_sessions"], item["right"], item["left"]
    ))
    selected = []
    for item in found:
        duplicate = False
        for prior in selected:
            intersection = max(
                0, min(item["right"], prior["right"]) - max(item["left"], prior["left"]) + 1
            )
            union = max(item["right"], prior["right"]) - min(item["left"], prior["left"]) + 1
            if abs(item["bottom"] - prior["bottom"]) <= 3 and intersection / union >= 0.75:
                duplicate = True
                break
        if not duplicate:
            selected.append(item)
            if len(selected) == 3:
                break
    return selected


def _market_screen(bars, index):
    if index < 169:
        return False
    average = sum(item["close"] for item in bars[index - 19:index + 1]) / 20
    earlier = sum(item["close"] for item in bars[index - 24:index - 4]) / 20
    prior_high = max(item["high"] for item in bars[index - 40:index])
    prior_volume = sum(item["volume"] for item in bars[index - 10:index]) / 10
    return (
        bars[index]["close"] > average * 0.97
        and average > earlier * 1.005
        and bars[index]["close"] > prior_high
        and prior_volume > 0
        and bars[index]["volume"] >= 1.2 * prior_volume
    )


def _money(value):
    return Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _reconcile(symbol, state, held, previous_orders):
    saved = state.get(symbol)
    if not isinstance(saved, dict):
        return None
    matching = [
        order for order in previous_orders
        if order.get("symbol") == symbol and order.get("signal_date") == saved.get("signal_date")
    ]
    if matching and matching[-1].get("action") == "sell" and matching[-1].get("status") == "filled" and held == 0:
        state.pop(symbol, None)
        return None
    if held > 0:
        if saved.get("pending") and matching and matching[-1].get("status") == "filled":
            saved["pending"] = False
            saved["filled"] = True
        return saved
    if saved.get("pending"):
        if matching:
            state.pop(symbol, None)
        return None
    if saved.get("filled"):
        state.pop(symbol, None)
        return None
    return saved


def decide(context):
    """Return proposals and bounded method-owned state for one close."""
    state = dict(context.get("state") or {})
    proposals = []
    positions = context["account"].get("positions", {})
    cash = _money(context["account"].get("cash", 0))
    previous_orders = context.get("previous_orders", [])
    for symbol, series in context.get("bars", {}).items():
        bars = series[-170:]
        if not bars:
            continue
        held = int(positions.get(symbol, 0))
        saved = _reconcile(symbol, state, held, previous_orders)
        if held > 0:
            if not isinstance(saved, dict) or "stop" not in saved or "target" not in saved:
                continue
            close = bars[-1]["close"]
            if close < saved["stop"] or close >= saved["target"]:
                proposals.append({
                    "symbol": symbol, "action": "sell",
                    "explanation": "Approved close exit: original stop breached or target reached.",
                    "sizing": {"shares": held}, "judgment": None,
                })
            continue
        if isinstance(saved, dict) and saved.get("pending"):
            continue
        index = len(bars) - 1
        if index < 169 or not _market_screen(bars, index):
            continue
        candidates = _candidates(bars, index)
        if not candidates:
            continue
        candidate = candidates[0]
        price = Decimal(str(bars[index]["close"]))
        gross = _money(price * SHARES)
        fee = _money(gross * FEE_RATE)
        if cash < gross + fee:
            continue
        left, right = candidate["left"], candidate["right"]
        judgment = (
            f"Assess only candidate dated {bars[left]['date']}–{bars[right]['date']}; "
            f"bottom {bars[candidate['bottom']]['date']}, handle through {bars[index-1]['date']}. "
            f"Numeric stop={candidate['stop']:.4f}, target={candidate['target']:.4f}. "
            "Apply all three approved shape criteria and cite visible dates."
        )
        proposals.append({
            "symbol": symbol, "action": "buy",
            "explanation": "Approved numeric market screen and first-ranked cup-and-handle candidate passed.",
            "sizing": {"shares": SHARES}, "judgment": judgment,
        })
        state[symbol] = {
            "pending": True, "signal_date": bars[index]["date"],
            "action": "buy",
            "stop": candidate["stop"], "target": candidate["target"],
            "left_rim": bars[left]["date"], "right_rim": bars[right]["date"],
            "bottom": bars[candidate["bottom"]]["date"],
        }
    return {"proposals": proposals, "state": state}

